SELECT b.book_id, b.seller_id, b.course_id, b.title, b.isbn, b.original_price,
       b.selling_price, b.condition_desc, b.cover_img_path, b.status, b.publish_time,
       u.username AS seller_name, u.credit_score AS credit_score,
       c.course_name AS course_name
FROM book b
LEFT JOIN `user` u ON b.seller_id = u.user_id
LEFT JOIN course c ON b.course_id = c.course_id


        AND b.title LIKE CONCAT('%', #{keyword}, '%')


        AND b.course_id = #{courseId}


        AND b.selling_price >= #{minPrice}


        AND b.selling_price <= #{maxPrice}


        AND b.status = #{status}


ORDER BY b.publish_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM book


        AND title LIKE CONCAT('%', #{keyword}, '%')


        AND course_id = #{courseId}


        AND selling_price >= #{minPrice}


        AND selling_price <= #{maxPrice}


        AND status = #{status}

SELECT book_id, seller_id, course_id, title, isbn, original_price, selling_price,
       condition_desc, cover_img_path, status, publish_time
FROM book WHERE book_id = #{bookId}

SELECT book_id, seller_id, course_id, title, isbn, original_price, selling_price, condition_desc, cover_img_path, status, publish_time FROM book WHERE status = '在售' AND course_id IN
#{cid}
ORDER BY publish_time DESC LIMIT #{limit}

SELECT book_id, seller_id, course_id, title, isbn, original_price, selling_price,
       condition_desc, cover_img_path, status, publish_time
FROM book WHERE isbn = #{isbn}
